function facts(core){
  const F=FACT[LANG];if(!F)return null;let n=0;
  const parts=core.split(' \u00b7 ').map(x=>{
    if(x==='no bonus'){n++;return F.nb}
    if(x==='double damage'){n++;return F.dd}
    const m=x.match(/^\+([\d.,]+)% vs\. ([a-z\/]+)$/);
    if(m){const cs=m[2].split('/');if(cs.every(c=>F.c[c])){n++;return F.t(m[1],cs.map(c=>F.c[c]).join('/'))}}
    return x});
  return n?parts.join(' \u00b7 '):null;
}
